mapper.update:
UPDATE my_plant_diary_image
SET ori_name = #{oriName},
    sys_name = #{sysName},
    url = #{url},
    hash = #{hash}
WHERE image_id = #{imageId}

mapper.select:
SELECT COUNT(*)
FROM my_plant_diary_image i
         JOIN my_plant_diary d ON i.diary_id = d.diary_id
WHERE i.image_id = #{imageId}
  AND d.user_plant_id = #{userPlantId}
